_TERMS = tuple(t for d in (2, 3) for t in combinations_with_replacement(range(4), d))


def _features(x):
    return np.column_stack((np.ones(len(x)), x, *(x[:, t].prod(axis=1) for t in _TERMS)))


def _fit_calibration(ref, raw):
